# Generated by test-lab — blind adversarial evaluation
"""CAE gap review protocol tests."""

from __future__ import annotations

import json

from ask.cae_gap_review import DEFAULT_CAE_REVIEWERS, parse_cae_reviewer_specs, run_cae_gap_review
from ask.run_state import AskRunState


def test_parse_default_cae_reviewers_separates_personas_from_roles():
    reviewers = parse_cae_reviewer_specs(None)

    assert reviewers == [
        {"persona": "Brandon", "role": "cae_policy_evidence"},
        {"persona": "Margaret", "role": "cae_technical_enforcement"},
        {"persona": "Jennifer", "role": "cae_control_mapping"},
    ]


def test_cae_gap_review_reroutes_only_failed_gate(tmp_path):
    calls: list[str] = []
    judge_calls = {"count": 0}

    def fake_turn(**kwargs):
        persona = kwargs["persona"]
        calls.append(persona)
        if persona == "Brandon":
            return json.dumps({"policy_findings": [{"source_id": "POL-1", "citation": "p.4"}], "evidence_limits": []}), "fake", None
        if persona == "Margaret":
            if calls.count("Margaret") == 1:
                return json.dumps({"enforcement_findings": [], "evidence_limits": ["technical evidence missing"]}), "fake", None
            return json.dumps({"enforcement_findings": [{"source_id": "TECH-1", "citation": "scan-7"}], "evidence_limits": []}), "fake", None
        if persona == "Jennifer":
            return json.dumps({"control_mappings": [{"control_id": "AC-2", "source_id": "CTL-1"}], "evidence_limits": []}), "fake", None
        judge_calls["count"] += 1
        if judge_calls["count"] == 1:
            return json.dumps({
                "review_id": "cae-case",
                "decision": "NEEDS_CLARIFICATION",
                "decision_summary": "Retrieved technical enforcement evidence is not yet cited.",
                "cited_basis": [{"source_id": "POL-1", "citation": "p.4", "usage": "policy requirement"}],
                "missing_evidence": [{
                    "missing_evidence_type": "technical_source",
                    "description": "Need cited MFA enforcement evidence.",
                    "needed_from": "technical_enforcement",
                }],
                "route_to": "technical_enforcement",
                "stop_reason": "required_input_missing",
                "final_status": "NEEDS_CLARIFICATION",
            }), "fake", None
        return json.dumps({
            "review_id": "cae-case",
            "decision": "PARTIAL_GAP_INDICATED",
            "decision_summary": "Retrieved policy, technical, and mapping evidence now indicate a partial gap.",
            "cited_basis": [{"source_id": "TECH-1", "citation": "scan-7", "usage": "technical enforcement signal"}],
            "missing_evidence": [],
            "route_to": "stop",
            "stop_reason": "analysis_complete_with_caveats",
            "final_status": "NEEDS_VERIFICATION",
        }), "fake", None

    run_state = AskRunState("cae-test", output_root=tmp_path)
    run_state.write_request({"command": "ask", "question": "review MFA", "scope": "security"})

    result = run_cae_gap_review(
        question="review MFA",
        scope="security",
        evidence_case={"claim": {"id": "case"}, "evidence": [{"source_id": "POL-1"}]},
        reviewers=DEFAULT_CAE_REVIEWERS,
        judge="Judge",
        max_rounds=3,
        model="fake",
        reasoning_effort="high",
        timeout=1,
        idle_timeout=30,
        heartbeat_interval=5,
        backend="scillm",
        dogpile_mode="auto",
        run_state=run_state,
        model_turn=fake_turn,
    )

    assert result["rounds_completed"] == 2
    assert result["halt_reason"] == "judge_terminal_decision"
    assert result["final_judge"]["decision"] == "PARTIAL_GAP_INDICATED"
    assert calls.count("Brandon") == 1
    assert calls.count("Jennifer") == 1
    assert calls.count("Margaret") == 2
    assert "approval" in result["answer"].lower()
    assert result["artifacts"]["cae_gap_review_json"].endswith("review.json")


def test_cae_gap_review_turn_failures_return_insufficient_evidence():
    def failing_turn(**kwargs):
        raise TimeoutError("model timed out")

    result = run_cae_gap_review(
        question="review MFA",
        scope="security",
        evidence_case={"claim": {"id": "case"}},
        reviewers=DEFAULT_CAE_REVIEWERS,
        judge="Judge",
        max_rounds=1,
        model="fake",
        reasoning_effort="high",
        timeout=1,
        idle_timeout=30,
        heartbeat_interval=5,
        backend="scillm",
        dogpile_mode="auto",
        model_turn=failing_turn,
    )

    assert result["halt_reason"] == "judge_terminal_decision"
    assert result["final_judge"]["decision"] == "INSUFFICIENT_EVIDENCE"
    assert result["final_judge"]["route_to"] == "human_reviewer"
